def parser():
    ascii = []
    red = [] 
    green = []
    blue = []
    for s in range(0,len(desired_output),24):
        string = desired_output[s:s+24]
        red.append(string[7:10])
        green.append(string[11:14])
        blue.append(string[15:18])
        ascii.append(string[19])
    return (red,green,blue,ascii)
    
